#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s1, s2;
    cin >> s1 >> s2;

    int target = 0, current = 0, unknown = 0;

    for (char c : s1)
        target += (c == '+') ? 1 : -1;

    for (char c : s2) {
        if (c == '+') ++current;
        else if (c == '-') --current;
        else ++unknown;
    }

    int requiredPlusNumerator = target - current + unknown;
    long double probability = 0.0L;

    if (requiredPlusNumerator >= 0 &&
        requiredPlusNumerator % 2 == 0) {
        int requiredPlus = requiredPlusNumerator / 2;

        if (requiredPlus <= unknown) {
            long double combinations = 1.0L;
            for (int i = 1; i <= requiredPlus; ++i)
                combinations *= static_cast<long double>(unknown - i + 1) / i;

            probability = combinations / powl(2.0L, unknown);
        }
    }

    cout << fixed << setprecision(12) << probability;
    return 0;
}

