    for (char c : s2) {
        if (c == '+') current++;
        else if (c == '-') current--;
        else unknown++;
    }

    int difference = target - current;
    double probability = 0.0;

    if (abs(difference) <= unknown && (unknown + difference) % 2 == 0) {
        int plusNeeded = (unknown + difference) / 2;
        double combinations = 1.0;

        for (int i = 1; i <= plusNeeded; ++i)
            combinations *= static_cast<double>(unknown - i + 1) / i;

        probability = combinations / pow(2.0, unknown);
    }

    cout << fixed << setprecision(12) << probability;
    return 0;
}

